mod solution;

fn main() {
    let cases = [
    (r#"[1, 7, 3, 6, 5, 6]"#, r#"3"#),
    (r#"[2, 1, -1]"#, r#"0"#),
    (r#"
[2, 1, -1]
"#, r#"0"#),
    (r#"  
[1, 7, 3, 6, 5, 6]
  "#, r#"3"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS equilibrium-index");
}
